package main

import (
	"errors"
	"net/url"
	"strings"
)

// parsePairQR accepts only complete ChatGo pairing links, including the
// fragment form generated by the desktop. Other QR contents never connect.
func parsePairQR(text string) (deepLink, error) {
	invalid := errors.New("这不是有效的 ChatGo 配对二维码，请在桌面重新生成")
	u, err := url.Parse(strings.TrimSpace(text))
	if err != nil || (u.Scheme != "chatgo" && u.Scheme != "https" && u.Scheme != "http") {
		return deepLink{}, invalid
	}
	link, err := parseDeepLink(text)
	if err != nil || link.kind != "pair" {
		return deepLink{}, invalid
	}
	link.relay = strings.TrimSpace(link.relay)
	link.desktop = strings.TrimSpace(link.desktop)
	link.code = strings.ToUpper(strings.TrimSpace(link.code))
	relay, err := url.Parse(link.relay)
	if err != nil || relay.Hostname() == "" || relay.User != nil || relay.RawQuery != "" || relay.Fragment != "" {
		return deepLink{}, invalid
	}
	switch relay.Scheme {
	case "http", "https", "ws", "wss":
	default:
		return deepLink{}, invalid
	}
	if link.desktop == "" || strings.ContainsAny(link.desktop, "/\\?# \t\r\n") || len(link.code) != 8 {
		return deepLink{}, invalid
	}
	for _, ch := range link.code {
		if !(ch >= 'A' && ch <= 'Z') && !(ch >= '0' && ch <= '9') {
			return deepLink{}, invalid
		}
	}
	return link, nil
}
